import pytest
from candidate import count_distinct_characters


def test_count_distinct_characters_simple_lowercase():
    assert count_distinct_characters('abc') == 3


def test_count_distinct_characters_case_insensitivity():
    assert count_distinct_characters('aAaBbCcc') == 3


def test_count_distinct_characters_with_digits():
    assert count_distinct_characters('1234567890') == 10


def test_count_distinct_characters_with_whitespace():
    assert count_distinct_characters('a b c') == 4


def test_count_distinct_characters_with_punctuation():
    assert count_distinct_characters('a,b.c!') == 6


def test_count_distinct_characters_with_unicode():
    assert count_distinct_characters('éÉäÄ') == 2


def test_count_distinct_characters_with_emojis():
    assert count_distinct_characters('😀😀😃😃😄') == 3


def test_count_distinct_characters_empty_string():
    assert count_distinct_characters('') == 0


def test_count_distinct_characters_long_string():
    long_str = 'a' * 1000
    assert count_distinct_characters(long_str) == 1
    long_str = ''.join(chr(i) for i in range(256))
    assert count_distinct_characters(long_str) == 256


def test_count_distinct_characters_return_type():
    result = count_distinct_characters('test')
    assert isinstance(result, int)


def test_count_distinct_characters_none_input():
    with pytest.raises(AttributeError):
        count_distinct_characters(None)


def test_count_distinct_characters_non_string_input_int():
    with pytest.raises(AttributeError):
        count_distinct_characters(123)


def test_count_distinct_characters_non_string_input_list():
    with pytest.raises(AttributeError):
        count_distinct_characters(['a', 'b'])


def test_count_distinct_characters_bytes_input():
    # bytes has a lower() method, but the function will treat each byte as an int in the set
    assert count_distinct_characters(b'ABCabc') == 6


def test_count_distinct_characters_mixed_case_and_symbols():
    assert count_distinct_characters('Aa!@#$%^&*()') == 10
